		{
			CreateDirectory( Combine( path1, path2 ) );
		}
		private static void CopyFile( string rootOrigin, string rootBackup, string path )
		{
			string originPath = Combine( rootOrigin, path );
			string backupPath = Combine( rootBackup, path );
