  private static final Map<Operator, Occur> opToOccur = new HashMap<Operator, Occur>();

  static {
    opToOccur.put(Operator.AND, Occur.MUST);
    opToOccur.put(Operator.ANDNOT, Occur.MUST_NOT);
    opToOccur.put(Operator.OR, Occur.SHOULD);
  }

