		/// Invalidates all folders.
		/// </summary>
    	void IFolderExplorerComponent.InvalidateFolders()
		{
			// check initialized
			if (!IsInitialized)
				return;
			// invalidate all folders, and update starting at the root
			_folderSystem.InvalidateFolders();
		}
